using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct LocationId : IEquatable<LocationId>, IComparable<LocationId>
    {
        public Guid Value { get; }

        public LocationId(Guid value)
        {
            Value = value;
        }

        public static LocationId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static LocationId NewRandom() => new LocationId(Guid.NewGuid());

        public static LocationId Parse(string text) => new LocationId(Guid.Parse(text));

        public static bool TryParse(string text, out LocationId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new LocationId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(LocationId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is LocationId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(LocationId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(LocationId left, LocationId right) => left.Equals(right);

        public static bool operator !=(LocationId left, LocationId right) => !left.Equals(right);
    }
}
